"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[755],{542:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>seminar-01-linear-regression</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="9e65daa5" class="cell markdown">\n<h1 id="семинар-1-линейная-регрессия">Семинар 1. Линейная регрессия</h1>\n<p><strong>Курс:</strong> Машинное обучение, 4 курс <strong>План\nзанятия:</strong></p>\n<ol>\n<li>Постановка задачи регрессии и функционал MSE.</li>\n<li>Аналитическое решение (нормальное уравнение).</li>\n<li>Градиентный спуск «руками».</li>\n<li>Регуляризация: Ridge и Lasso.</li>\n<li>Переобучение полиномиальной модели.</li>\n</ol>\n<blockquote>\n<p>Всё, что нужно для повторения: <code>numpy</code>,\n<code>matplotlib</code>, <code>scikit-learn</code>.</p>\n</blockquote>\n</div>\n<div id="ebcfd08a" class="cell code" data-execution_count="1" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:47.728637Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:47.728332Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:48.168515Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:48.167732Z&quot;}">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(<span class="dv">42</span>)</span></code></pre></div>\n</div>\n<div id="db15537d" class="cell markdown">\n<h2 id="1-постановка-задачи">1. Постановка задачи</h2>\n<p>Дана выборка\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><msubsup><mo stretchy="false" form="postfix">)</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></msubsup></mrow><annotation encoding="application/x-tex">(x_i, y_i)_{i=1}^{\\ell}</annotation></semantics></math>.\nИщем линейную модель</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>w</mi><mn>0</mn></msub><mo>+</mo><msub><mi>w</mi><mn>1</mn></msub><mi>x</mi><mo>,</mo></mrow><annotation encoding="application/x-tex">a(x) = w_0 + w_1 x,</annotation></semantics></math></p>\n<p>минимизируя средний квадрат ошибки</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mn>2</mn></msup><mo>→</mo><munder><mi>min</mi><mi>w</mi></munder><mi>.</mi></mrow><annotation encoding="application/x-tex">Q(w) = \\frac{1}{\\ell}\\sum_{i=1}^{\\ell} \\bigl(a(x_i) - y_i\\bigr)^2 \\to \\min_w.</annotation></semantics></math></p>\n<p>Сгенерируем данные с известными коэффициентами, чтобы было с чем\nсравнивать.</p>\n</div>\n<div id="0df063f4" class="cell code" data-execution_count="2" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:48.170347Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:48.170188Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:48.300990Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:48.300700Z&quot;}">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">60</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a>w_true <span class="op">=</span> np.array([<span class="fl">2.5</span>, <span class="op">-</span><span class="fl">1.7</span>])          <span class="co"># [свободный член, наклон]</span></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>X <span class="op">=</span> np.linspace(<span class="op">-</span><span class="dv">3</span>, <span class="dv">3</span>, n)</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a>noise <span class="op">=</span> rng.normal(<span class="dv">0</span>, <span class="fl">1.2</span>, size<span class="op">=</span>n)</span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a>y <span class="op">=</span> w_true[<span class="dv">0</span>] <span class="op">+</span> w_true[<span class="dv">1</span>] <span class="op">*</span> X <span class="op">+</span> noise</span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a>plt.scatter(X, y, s<span class="op">=</span><span class="dv">28</span>, color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>, alpha<span class="op">=</span><span class="fl">0.75</span>, label<span class="op">=</span><span class="st">&quot;наблюдения&quot;</span>)</span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a>plt.plot(X, w_true[<span class="dv">0</span>] <span class="op">+</span> w_true[<span class="dv">1</span>] <span class="op">*</span> X, color<span class="op">=</span><span class="st">&quot;#0f172a&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;истинная зависимость&quot;</span>)</span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a>plt.xlabel(<span class="st">&quot;$x$&quot;</span>)<span class="op">;</span> plt.ylabel(<span class="st">&quot;$y$&quot;</span>)</span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a>plt.title(<span class="st">&quot;Синтетические данные&quot;</span>)</span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>plt.legend()</span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="e3bbbc87" class="cell markdown">\n<h2 id="2-аналитическое-решение">2. Аналитическое решение</h2>\n<p>Для матрицы объекты–признаки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>X</mi><annotation encoding="application/x-tex">X</annotation></semantics></math>\n(с добавленным столбцом единиц) оптимум даётся нормальным уравнением</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>w</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>⊤</mi></msup><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>⊤</mi></msup><mi>y</mi><mi>.</mi></mrow><annotation encoding="application/x-tex">w^* = (X^\\top X)^{-1} X^\\top y.</annotation></semantics></math></p>\n</div>\n<div id="dd639fcd" class="cell code" data-execution_count="3" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:48.302516Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:48.302415Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:48.305170Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:48.304941Z&quot;}">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>X_design <span class="op">=</span> np.column_stack([np.ones_like(X), X])          <span class="co"># добавляем константный признак</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>w_analytic <span class="op">=</span> np.linalg.solve(X_design.T <span class="op">@</span> X_design, X_design.T <span class="op">@</span> y)</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Истинные коэффициенты:      &quot;</span>, np.<span class="bu">round</span>(w_true, <span class="dv">3</span>))</span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Аналитическое решение МНК:  &quot;</span>, np.<span class="bu">round</span>(w_analytic, <span class="dv">3</span>))</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>Истинные коэффициенты:       [ 2.5 -1.7]\nАналитическое решение МНК:   [ 2.578 -1.659]\n</code></pre>\n</div>\n</div>\n<div id="ec1b5058" class="cell code" data-execution_count="4" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:48.306266Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:48.306175Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:55.548711Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:55.548302Z&quot;}">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>model <span class="op">=</span> LinearRegression().fit(X.reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>), y)</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;sklearn LinearRegression:   &quot;</span>, np.<span class="bu">round</span>([model.intercept_, model.coef_[<span class="dv">0</span>]], <span class="dv">3</span>))</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>sklearn LinearRegression:    [ 2.578 -1.659]\n</code></pre>\n</div>\n</div>\n<div id="019efe30" class="cell markdown">\n<p>Значения совпадают: <code>LinearRegression</code> внутри решает ту же\nзадачу (через SVD, что устойчивее явного обращения матрицы).</p>\n<h2 id="3-градиентный-спуск">3. Градиентный спуск</h2>\n<p>Градиент функционала по вектору весов:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>∇</mi><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>2</mn><mi>ℓ</mi></mfrac><msup><mi>X</mi><mi>⊤</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>w</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\\nabla Q(w) = \\frac{2}{\\ell} X^\\top (Xw - y).</annotation></semantics></math></p>\n<p>Реализуем спуск и посмотрим на кривую обучения.</p>\n</div>\n<div id="f14e027e" class="cell code" data-execution_count="5" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:55.550586Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:55.550362Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:55.556696Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:55.556269Z&quot;}">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> gradient_descent(X, y, lr<span class="op">=</span><span class="fl">0.05</span>, n_steps<span class="op">=</span><span class="dv">200</span>):</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Простейший полный (batch) градиентный спуск для MSE.&quot;&quot;&quot;</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>    w <span class="op">=</span> np.zeros(X.shape[<span class="dv">1</span>])</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    history <span class="op">=</span> []</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> _ <span class="kw">in</span> <span class="bu">range</span>(n_steps):</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>        residual <span class="op">=</span> X <span class="op">@</span> w <span class="op">-</span> y</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>        loss <span class="op">=</span> np.mean(residual <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>        history.append(loss)</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a>        grad <span class="op">=</span> <span class="dv">2</span> <span class="op">/</span> <span class="bu">len</span>(y) <span class="op">*</span> X.T <span class="op">@</span> residual</span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>        w <span class="op">-=</span> lr <span class="op">*</span> grad</span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> w, np.array(history)</span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-13"><a href="#cb7-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-14"><a href="#cb7-14" aria-hidden="true" tabindex="-1"></a>w_gd, history <span class="op">=</span> gradient_descent(X_design, y, lr<span class="op">=</span><span class="fl">0.05</span>, n_steps<span class="op">=</span><span class="dv">200</span>)</span>\n<span id="cb7-15"><a href="#cb7-15" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Градиентный спуск:          &quot;</span>, np.<span class="bu">round</span>(w_gd, <span class="dv">3</span>))</span>\n<span id="cb7-16"><a href="#cb7-16" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Итоговый MSE:               &quot;</span>, <span class="bu">round</span>(history[<span class="op">-</span><span class="dv">1</span>], <span class="dv">4</span>))</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>Градиентный спуск:           [ 2.578 -1.659]\nИтоговый MSE:                0.8688\n</code></pre>\n</div>\n</div>\n<div id="2fb63b12" class="cell code" data-execution_count="6" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:55.558264Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:55.558122Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:55.626990Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:55.626727Z&quot;}">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a>plt.plot(history, color<span class="op">=</span><span class="st">&quot;#06b6d4&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>plt.axhline(np.mean((X_design <span class="op">@</span> w_analytic <span class="op">-</span> y) <span class="op">**</span> <span class="dv">2</span>), color<span class="op">=</span><span class="st">&quot;#ef4444&quot;</span>, ls<span class="op">=</span><span class="st">&quot;--&quot;</span>,</span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>            label<span class="op">=</span><span class="st">&quot;MSE аналитического решения&quot;</span>)</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>plt.xlabel(<span class="st">&quot;итерация&quot;</span>)<span class="op">;</span> plt.ylabel(<span class="st">&quot;MSE&quot;</span>)</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>plt.title(<span class="st">&quot;Сходимость градиентного спуска&quot;</span>)</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>plt.legend()</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="0c39273d" class="cell markdown">\n<h2 id="4-регуляризация">4. Регуляризация</h2>\n<p>Когда признаков много и они скоррелированы, веса «разлетаются». Ridge\nдобавляет штраф\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msubsup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">\\lambda\\|w\\|_2^2</annotation></semantics></math>,\nLasso —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo stretchy="false" form="postfix">∥</mo><mi>w</mi><msub><mo stretchy="false" form="postfix">∥</mo><mn>1</mn></msub></mrow><annotation encoding="application/x-tex">\\lambda\\|w\\|_1</annotation></semantics></math>\n(и зануляет часть весов).</p>\n</div>\n<div id="a9c9e901" class="cell code" data-execution_count="7" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:55.628203Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:55.628120Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:55.640729Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:55.640484Z&quot;}">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> Ridge, Lasso</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> make_pipeline</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> mean_squared_error</span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>X_tr, X_te, y_tr, y_te <span class="op">=</span> train_test_split(X.reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>), y, test_size<span class="op">=</span><span class="fl">0.3</span>, random_state<span class="op">=</span><span class="dv">0</span>)</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> name, estimator <span class="kw">in</span> [</span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a>    (<span class="st">&quot;Без регуляризации&quot;</span>, LinearRegression()),</span>\n<span id="cb10-11"><a href="#cb10-11" aria-hidden="true" tabindex="-1"></a>    (<span class="st">&quot;Ridge (alpha=1)   &quot;</span>, Ridge(alpha<span class="op">=</span><span class="fl">1.0</span>)),</span>\n<span id="cb10-12"><a href="#cb10-12" aria-hidden="true" tabindex="-1"></a>    (<span class="st">&quot;Lasso (alpha=0.1) &quot;</span>, Lasso(alpha<span class="op">=</span><span class="fl">0.1</span>)),</span>\n<span id="cb10-13"><a href="#cb10-13" aria-hidden="true" tabindex="-1"></a>]:</span>\n<span id="cb10-14"><a href="#cb10-14" aria-hidden="true" tabindex="-1"></a>    pipe <span class="op">=</span> make_pipeline(PolynomialFeatures(degree<span class="op">=</span><span class="dv">9</span>), estimator).fit(X_tr, y_tr)</span>\n<span id="cb10-15"><a href="#cb10-15" aria-hidden="true" tabindex="-1"></a>    mse_tr <span class="op">=</span> mean_squared_error(y_tr, pipe.predict(X_tr))</span>\n<span id="cb10-16"><a href="#cb10-16" aria-hidden="true" tabindex="-1"></a>    mse_te <span class="op">=</span> mean_squared_error(y_te, pipe.predict(X_te))</span>\n<span id="cb10-17"><a href="#cb10-17" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">  train MSE = </span><span class="sc">{</span>mse_tr<span class="sc">:5.2f}</span><span class="ss">   test MSE = </span><span class="sc">{</span>mse_te<span class="sc">:5.2f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>Без регуляризации  train MSE =  0.46   test MSE = 10.34\nRidge (alpha=1)     train MSE =  0.47   test MSE =  8.31\nLasso (alpha=0.1)   train MSE =  0.59   test MSE =  2.57\n</code></pre>\n</div>\n<div class="output stream stderr">\n<pre><code>/opt/anaconda3/lib/python3.13/site-packages/sklearn/linear_model/_coordinate_descent.py:695: ConvergenceWarning: Objective did not converge. You might want to increase the number of iterations, check the scale of the features or consider increasing regularisation. Duality gap: 1.501e+01, tolerance: 3.918e-02\n  model = cd_fast.enet_coordinate_descent(\n</code></pre>\n</div>\n</div>\n<div id="9d17a14d" class="cell markdown">\n<h2 id="5-переобучение-полиномиальной-модели">5. Переобучение\nполиномиальной модели</h2>\n<p>Наглядно: чем выше степень полинома, тем точнее модель описывает\nобучающую выборку и тем хуже — новые данные.</p>\n</div>\n<div id="9d8477dd" class="cell code" data-execution_count="8" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T11:09:55.641890Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T11:09:55.641790Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T11:09:55.771027Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T11:09:55.770755Z&quot;}">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> np.linspace(<span class="op">-</span><span class="fl">3.2</span>, <span class="fl">3.2</span>, <span class="dv">300</span>).reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">3.6</span>), sharey<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, degree <span class="kw">in</span> <span class="bu">zip</span>(axes, [<span class="dv">1</span>, <span class="dv">4</span>, <span class="dv">15</span>]):</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>    pipe <span class="op">=</span> make_pipeline(PolynomialFeatures(degree), LinearRegression()).fit(X_tr, y_tr)</span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>    ax.scatter(X_tr, y_tr, s<span class="op">=</span><span class="dv">22</span>, color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>, alpha<span class="op">=</span><span class="fl">0.7</span>, label<span class="op">=</span><span class="st">&quot;train&quot;</span>)</span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a>    ax.scatter(X_te, y_te, s<span class="op">=</span><span class="dv">22</span>, color<span class="op">=</span><span class="st">&quot;#f59e0b&quot;</span>, alpha<span class="op">=</span><span class="fl">0.9</span>, label<span class="op">=</span><span class="st">&quot;test&quot;</span>)</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a>    ax.plot(grid, pipe.predict(grid), color<span class="op">=</span><span class="st">&quot;#0f172a&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a>    ax.set_ylim(y.<span class="bu">min</span>() <span class="op">-</span> <span class="dv">2</span>, y.<span class="bu">max</span>() <span class="op">+</span> <span class="dv">2</span>)</span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;степень </span><span class="sc">{</span>degree<span class="sc">}</span><span class="ch">\\n</span><span class="ss">test MSE = </span><span class="sc">{</span>mean_squared_error(y_te, pipe.predict(X_te))<span class="sc">:.2f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].legend()</span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()</span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="4261854c" class="cell markdown">\n<h2 id="задание-для-самостоятельной-работы">Задание для самостоятельной\nработы</h2>\n<ol>\n<li>Реализуйте стохастический градиентный спуск (SGD) и сравните\nскорость сходимости с полным градиентным спуском при одинаковом числе\nпроходов по выборке.</li>\n<li>Постройте зависимость test MSE от <code>alpha</code> для Ridge на\nлогарифмической сетке <code>np.logspace(-3, 3, 20)</code> и найдите\nоптимальное значение по кросс-валидации.</li>\n<li>Объясните, почему Lasso зануляет часть коэффициентов, а Ridge —\nнет.</li>\n</ol>\n<p><strong>Дедлайн:</strong> до следующего семинара.</p>\n</div>\n</body>\n</html>\n'}}]);